DROP TABLE IF EXISTS `inventory_bins`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inventory_bins` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `warehouse_id` char(36) NOT NULL,
  `code` varchar(60) NOT NULL,
  `aisle` varchar(60) DEFAULT NULL,
  `rack` varchar(60) DEFAULT NULL,
  `description` varchar(180) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `inventory_bins_warehouse_id_code_key` (`warehouse_id`,`code`),
  KEY `inventory_bins_company_id_status_idx` (`company_id`,`status`),
  CONSTRAINT `inventory_bins_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `inventory_bins_warehouse_id_fkey` FOREIGN KEY (`warehouse_id`) REFERENCES `inventory_warehouses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
