DROP TABLE IF EXISTS `inventory_fulfillments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inventory_fulfillments` (
  `id` char(36) NOT NULL,
  `company_id` char(36) NOT NULL,
  `sales_order_id` char(36) NOT NULL,
  `order_no` varchar(60) NOT NULL,
  `customer` varchar(180) NOT NULL,
  `requested_items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`requested_items`)),
  `shortage_items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`shortage_items`)),
  `status` varchar(50) NOT NULL DEFAULT 'PENDING_CHECK',
  `notes` text DEFAULT NULL,
